    @Test(arguments: corpus)
    func theLayRotationMatchesThreeJS(row: ([Double], [Double], [Double], [Double])) throws {
        let pose = try #require(Pose(columnMajor: row.2))
        let laid = pose.laidFlat(onFaceNormal: SIMD3(row.1[0], row.1[1], row.1[2]))
        let want = try #require(Pose(columnMajor: row.3))
        #expect(laid.isSame(as: want, tolerance: 1e-9), "euler \(row.0) normal \(row.1)")
    }

    @Test(arguments: corpus)
    func theLaidFaceLooksStraightDown(row: ([Double], [Double], [Double], [Double])) throws {
        let pose = try #require(Pose(columnMajor: row.2))
        let n = SIMD3(row.1[0], row.1[1], row.1[2])
        let down = (pose.laidFlat(onFaceNormal: n).rotation * n)
        // the half-turn branch of setFromUnitVectors is only as exact as the input is a unit vector, and a normal
        // a hair off straight up (1e-5) is that case: it lands within 1e-4 of down, as three.js does
        #expect(simd_length(down - Pose.down) < 1e-4)
    }

    // MARK: the mode

    func rig() throws -> (PartSession, LayFaceModel, CorePart) {
        let device = try #require(MTLCreateSystemDefaultDevice(), "no Metal device")
        let part = try #require(CorePart(part: try TestParts.cube(), device: device))
        let s = PartSession(parts: [part])
        return (s, LayFaceModel(session: s, controller: nil), part)
    }

    /// A face of the cube whose model-frame normal is `n`.
    func face(of part: CorePart, facing n: SIMD3<Double>) throws -> Int {
        try #require((0..<part.faceCount).first { part.faceNormal($0).map { simd_dot($0, n) > 0.99 } ?? false })
    }

    @Test func aClickLaysTheFaceAsOneUndoStepAndDisarms() throws {
        let (s, lay, part) = try rig()
        lay.arm()
        #expect(lay.armed && lay.title == "Click a face to lay it flat — Esc cancels")
        let f = try face(of: part, facing: SIMD3(1, 0, 0))
        lay.click(part: 0, face: f)
        #expect(!lay.armed && lay.title == "Lay a face flat")
        #expect(simd_length(s.pose.rotation * SIMD3(1, 0, 0) - Pose.down) < 1e-6)
        #expect(s.history.undoStack.count == 1)
        s.undo()
        #expect(s.pose == .identity)
        s.redo()
        #expect(simd_length(s.pose.rotation * SIMD3(1, 0, 0) - Pose.down) < 1e-6)
    }

    @Test func cancelLeavesThePoseAndHistoryUntouched() throws {
        let (s, lay, part) = try rig()
        s.rotate90(about: .y)
        let before = s.pose, steps = s.history.undoStack.count
        lay.arm()
        lay.cancel()
        #expect(!lay.armed && s.pose == before && s.history.undoStack.count == steps)
        // a click after cancelling does nothing: only an armed mode lays
        lay.click(part: 0, face: try face(of: part, facing: SIMD3(1, 0, 0)))
        #expect(s.pose == before && s.history.undoStack.count == steps)
    }

    @Test func clickingAFaceThatIsAlreadyDownRecordsNoStep() throws {
        let (s, lay, part) = try rig()
        lay.arm()
        lay.click(part: 0, face: try face(of: part, facing: SIMD3(0, 0, -1)))
        #expect(s.pose.isSame(as: .identity) && !s.canUndo && !lay.armed)
    }

    @Test func aClickWithNoSuchFaceLeavesItArmed() throws {
        let (s, lay, part) = try rig()
        lay.arm()
        lay.click(part: 0, face: part.faceCount + 5)
        #expect(lay.armed && s.pose == .identity)
    }

    @Test func itNeedsAPartToArm() {
        let lay = LayFaceModel(session: PartSession(), controller: nil)
        lay.arm()
        #expect(!lay.armed)
    }

    @Test func toggleArmsAndDisarms() throws {
        let (_, lay, _) = try rig()
        lay.toggle(); #expect(lay.armed)
        lay.toggle(); #expect(!lay.armed)
    }
}
